// Rental desk: KPI counts + selected equipment. Runs on rentals.onDataQuerySuccess, the page's onPageLoad and rentalQueue.onRowClicked
const rows = queries.rentals.data || [];
const selId = components.rentalQueue?.selectedRow?.id ?? variables.selectedRentalId;
const r = rows.find(x => x.id === selId) || rows[0] || {};
const fmt = v => v ? new Date(v).toLocaleString('en-US', {month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit', timeZone: 'America/Los_Angeles'}) : 'Not scheduled';
const rate = Number(r.daily_rate);
const today = Date.parse('2026-09-13T12:00:00-07:00');
return {
  late: rows.filter(x => x.state === 'On rent' && Date.parse(x.return_at) < today).length,
  next: rows.filter(x => x.state === 'Reserved').length,
  ready: rows.filter(x => x.state === 'Ready').length,
  total: rows.length,
  code: [r.asset_code, r.category].filter(Boolean).join(' · '),
  equipment: r.equipment || '',
  state: r.state || '',
  fields: [
    { label: 'Customer', value: r.customer || 'No current booking' },
    { label: 'Collection', value: fmt(r.pickup_at) },
    { label: 'Due back', value: fmt(r.return_at) },
    { label: 'Daily rate', value: Number.isFinite(rate) ? rate.toLocaleString('en-US', {style: 'currency', currency: 'USD'}) : '' }
  ],
  notes: r.notes || ''
};
